import { useId } from "react";
import { cn } from "../../lib/utils";
import { AI, HUES, MARK_RADIUS, TILES, TILES_SMALL, WORD, WORDMARK } from "./logo-paths";

/*
 * The Xhibit AI "Window" logo: a rounded square cut by an X into four tiles, one per brand hue.
 * The four sides are a frame (the thing on display); the X is how you look through it.
 * Generated by `npm run logo` (scripts/logo.mjs). Brand files live in public/brand/.
 */

type Tone = "light" | "dark";

function Tiles({ tone, small, clipId }: { tone: Tone; small?: boolean; clipId: string }) {
  const hues = HUES[tone];
  return (
    <>
      <defs>
        <clipPath id={clipId}>
          <rect width="100" height="100" rx={MARK_RADIUS} />
        </clipPath>
      </defs>
      <g clipPath={`url(#${clipId})`}>
        {(small ? TILES_SMALL : TILES).map((d, i) => (
          <path key={i} d={d} fill={hues[i]} />
        ))}
      </g>
    </>
  );
}

/** The mark on its own. Use `small` below ~32 px so the four colours stay separate. */
export function LogoMark({ className, tone = "light", small }: { className?: string; tone?: Tone; small?: boolean }) {
  const id = useId();
  return (
    <svg viewBox="0 0 100 100" className={className} aria-hidden="true">
      <Tiles tone={tone} small={small} clipId={id} />
    </svg>
  );
}

/** Mark + "xhibit ai" wordmark. `light` tone for dark backgrounds. */
export function Logo({ tone = "ink", className }: { tone?: "ink" | "light"; className?: string }) {
  const id = useId();
  const onDark = tone === "light";
  return (
    <svg viewBox={`0 0 ${WORDMARK.w} ${WORDMARK.h}`} className={cn("block h-[1.7rem] w-auto", className)} role="img" aria-label="Xhibit AI">
      <g transform={WORDMARK.markTransform}>
        <Tiles tone={onDark ? "dark" : "light"} clipId={id} />
      </g>
      <g transform={`translate(0 ${WORDMARK.baseY})`}>
        <path transform={`translate(${WORD.x} 0)`} d={WORD.d} fill={onDark ? "#ffffff" : "#0b0b0c"} />
        <path transform={`translate(${AI.x} 0)`} d={AI.d} fill={onDark ? "rgba(255,255,255,.5)" : "#76767b"} />
      </g>
    </svg>
  );
}
